// Visual feedback follows acknowledged game state; it never chooses outcomes.
const euro=n=>'€'+Math.abs(n).toLocaleString('ja-JP');
const pipPositions={1:[5],2:[1,9],3:[1,5,9],4:[1,3,7,9],5:[1,3,5,7,9],6:[1,3,4,6,7,9]};
const cardLine=/^(旅の写真|交通券を|旅程を|手続き確認|案内人から|景観整備|三歩戻|観光ガイド|旅先から|荷物の修理|次の旅は|忘れ物の手続き|旅人仲間|資料の寄付|三歩前|旅の記録)/;
function additions(previous,next){for(let n=Math.min(previous.length,next.length);n>=0;n--)if(previous.slice(-n||previous.length).join('\n')===next.slice(0,n).join('\n'))return next.slice(n);return next;}
export class JourneyEffects{
 constructor(){this.previous=null;this.pending=false;this.timers=[];this.flights=new Map();this.transients=new Set();this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.layer=document.createElement('div');this.layer.className='journey-effects';this.layer.setAttribute('aria-live','polite');this.layer.setAttribute('aria-atomic','false');document.getElementById('game').append(this.layer);}
 later(fn,ms){const id=setTimeout(()=>{this.timers=this.timers.filter(x=>x!==id);fn();},ms);this.timers.push(id);return id;}
 reset(){this.previous=null;this.pending=false;this.timers.forEach(clearTimeout);this.timers=[];this.layer.replaceChildren();for(const node of this.flights.values())node.remove();this.flights.clear();for(const node of this.transients)node.remove();this.transients.clear();clearInterval(this.spin);this.drawDice([0,0]);}
 drawDice(values,rolling=false){const box=document.getElementById('dice');box.replaceChildren();box.classList.toggle('rolling',rolling);box.setAttribute('aria-label',rolling?'サイコロを振っています':values.every(Boolean)?`サイコロ ${values.join(' と ')}、合計 ${values[0]+values[1]}`:'サイコロを振って出発');const pair=document.createElement('span');pair.className='dice-pair';for(const value of values){const die=document.createElement('span');die.className='die';die.dataset.value=value;die.setAttribute('aria-hidden','true');for(let n=1;n<=9;n++){const pip=document.createElement('i');pip.className='die-pip';pip.style.opacity=pipPositions[value]?.includes(n)?'1':'0';die.append(pip);}pair.append(die);}box.append(pair);const caption=document.createElement('small');caption.textContent=rolling?'ROLLING…':values.every(Boolean)?`${values[0]} + ${values[1]} = ${values[0]+values[1]}`:'YOUR JOURNEY STARTS HERE';box.append(caption);}
 startRoll(){if(this.pending)return false;this.pending=true;this.spinDice();return true;}
 spinDice(){clearInterval(this.spin);let frame=0;this.drawDice([1,6],!this.reduced.matches);if(!this.reduced.matches)this.spin=setInterval(()=>{frame++;this.drawDice([frame%6+1,(frame*3+2)%6+1],true);},85);}
 cancelPending(){if(!this.pending)return;this.pending=false;clearInterval(this.spin);this.spin=null;this.drawDice(this.previous?.dice||[0,0]);}
 observe(state){if(!state)return;const prev=this.previous;if(prev&&state.revision<=prev.revision)return;this.previous=structuredClone(state);if(!prev){this.drawDice(state.dice);return;}this.pending=false;const logs=additions(prev.log,state.log),rolled=logs.some(x=>x.includes(' のサイコロ: '));if(rolled){this.spinDice();clearTimeout(this.diceFinish);this.timers=this.timers.filter(id=>id!==this.diceFinish);this.diceFinish=this.later(()=>{clearInterval(this.spin);this.spin=null;this.drawDice(state.dice);},this.reduced.matches?0:650);}else if(!this.spin)this.drawDice(state.dice);
 for(const p of state.players){const old=prev.players.find(x=>x.id===p.id);if(!old)continue;const delta=p.money-old.money;if(delta)this.later(()=>this.money(p,delta),rolled&&!this.reduced.matches?1200:0);if(old.position!==p.position)this.later(()=>this.travel(old,p,rolled?state.dice[0]+state.dice[1]:null),rolled&&!this.reduced.matches?650:0);}
 for(const line of logs.filter(x=>cardLine.test(x)))this.later(()=>this.card(line),rolled&&!this.reduced.matches?1300:0);
 const latest=logs.filter(x=>!cardLine.test(x)).slice(-1)[0];if(latest)this.announce(latest);
 }
 announce(text){this.layer.querySelector('.journey-event')?.remove();const event=document.createElement('p');event.className='journey-event';event.textContent=text;this.layer.append(event);this.later(()=>event.remove(),4500);}
 money(player,delta){const panel=[...document.querySelectorAll('.player[data-player-id]')].find(x=>x.dataset.playerId===player.id);if(!panel)return;const badge=document.createElement('span');badge.className='money-flight '+(delta>0?'positive':'negative');badge.textContent=(delta>0?'+':'−')+euro(delta);badge.setAttribute('aria-label',player.name+(delta>0?' の収入 ':' の支払い ')+euro(delta));const rect=panel.getBoundingClientRect();Object.assign(badge.style,{position:'fixed',left:Math.max(8,Math.min(innerWidth-115,rect.left+rect.width/2-45))+'px',top:Math.max(12,Math.min(innerHeight-80,rect.top+20))+'px',pointerEvents:'none',zIndex:100});document.body.append(badge);this.transients.add(badge);if(!this.reduced.matches)badge.animate([{opacity:0,transform:'translateY(12px) scale(.8)'},{opacity:1,transform:'translateY(0) scale(1.1)',offset:.2},{opacity:1,offset:.75},{opacity:0,transform:'translateY(-38px)'}],{duration:1800,fill:'forwards'});this.later(()=>{badge.remove();this.transients.delete(badge);},1900);}
 travel(old,p,steps){if(this.reduced.matches)return;const tiles=[...document.querySelectorAll('[data-tile-id]')],rect=id=>tiles.find(t=>Number(t.dataset.tileId)===id)?.getBoundingClientRect();const start=rect(old.position);if(!start||!start.width)return;this.flights.get(p.id)?.remove();const dot=document.createElement('span');dot.className='traveler-flight';dot.textContent='●';dot.setAttribute('aria-hidden','true');const token=[...document.querySelectorAll('.token[data-player-id]')].find(t=>t.dataset.playerId===p.id);dot.style.color=token?.style.getPropertyValue('--player')||'#dc915a';Object.assign(dot.style,{position:'fixed',left:'0',top:'0',pointerEvents:'none',zIndex:90});document.body.append(dot);this.flights.set(p.id,dot);const direct=steps&&((old.position+steps)%40===p.position);const path=direct?Array.from({length:steps+1},(_,i)=>(old.position+i)%40):[old.position,p.position];const frames=path.map(id=>rect(id)).filter(Boolean).map(r=>({transform:`translate(${r.left+r.width/2-8}px,${r.top+r.height/2-8}px)`}));dot.animate(frames,{duration:Math.min(550,path.length*70),easing:'ease-in-out',fill:'both'}).onfinish=()=>{dot.remove();if(this.flights.get(p.id)===dot)this.flights.delete(p.id);};}
 card(text){this.layer.querySelector('.journey-card')?.remove();const card=document.createElement('button');card.type='button';card.className='journey-card';const kicker=document.createElement('small');kicker.textContent='TRAVEL CHANCE';const content=document.createElement('strong');content.textContent='旅のカードをめくる';const hint=document.createElement('span');hint.textContent='タップで結果を見る';card.append(kicker,content,hint);const reveal=()=>{if(!card.isConnected)return;card.classList.add('revealed');content.textContent=text;hint.textContent='この結果は旅に反映されました';card.onclick=()=>card.remove();};card.onclick=reveal;this.layer.append(card);this.later(reveal,2400);this.later(()=>card.remove(),10000);}
}
